#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_DIGITS 20

typedef struct {
    int digits[MAX_DIGITS]; // digits[0] is most significant digit
    int len;
} BigNum;

// Multiply BigNum by integer x, keep only first MAX_DIGITS digits (from left)
void multiply(BigNum *num, int x) {
    long long carry = 0;
    for (int i = num->len - 1; i >= 0; i--) {
        long long cur = (long long)num->digits[i] * x + carry;
        num->digits[i] = (int)(cur % 10);
        carry = cur / 10;
    }
    // If carry remains, shift digits right and put carry digits at front
    while (carry > 0) {
        if (num->len == MAX_DIGITS) {
            // drop last digit
            for (int i = num->len - 1; i > 0; i--) {
                num->digits[i] = num->digits[i - 1];
            }
            num->digits[0] = (int)(carry % 10);
            carry /= 10;
        } else {
            // shift right
            for (int i = num->len; i > 0; i--) {
                num->digits[i] = num->digits[i - 1];
            }
            num->digits[0] = (int)(carry % 10);
            carry /= 10;
            num->len++;
        }
    }
    // If length > MAX_DIGITS, truncate from right
    if (num->len > MAX_DIGITS) {
        num->len = MAX_DIGITS;
    }
}

// Remove trailing zeros from BigNum (digits from right)
void remove_trailing_zeros(BigNum *num) {
    while (num->len > 1 && num->digits[num->len - 1] == 0) {
        num->len--;
    }
}

// Convert BigNum to string
void bignum_to_str(BigNum *num, char *buf) {
    for (int i = 0; i < num->len; i++) {
        buf[i] = num->digits[i] + '0';
    }
    buf[num->len] = 0;
}

