            x /= 5;
            trailing_zeros--;
        }
        while (x % 2 == 0 && trailing_zeros > 0) {
            x /= 2;
            trailing_zeros--;
        }
        logSum += log10((double)x);
    }
    // trailing_zeros restored for output
    trailing_zeros = count5 < count2 ? count5 : count2;

